class Stack:
    def __init__(self):
    # Stack implementation using Python list
    self.stack = []

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        return self.stack.pop() if self.stack else None

    def is_empty(self):
        return len(self.stack) == 0


class QueueUsingTwoStacks:
    def __init__(self):
        # Initialize two empty stacks for enqueue and dequeue operations
        self.enqueue_stack = Stack()
        self.dequeue_stack = Stack()

    def enqueue(self, item):
        self.enqueue_stack.push(item)  # Add element to the enqueue stack

    def dequeue(self):
        # Check if both stacks are empty or dequeue_stack is empty
        if self.is_empty():
            return None  # Queue is empty
        elif self.dequeue_stack.is_empty():
            # Transfer elements from enqueue stack to dequeue stack if needed
            while not self.enqueue_stack.is_empty():
                self.dequeue_stack.push(self.enqueue_stack.pop())

        return self.dequeue_stack.pop()  # Return and remove item from dequeue stack

    def is_empty(self):
        return self.enqueue_stack.is_empty() and self.dequeue_stack.is_empty()


